js-mh-fill-template.wrong-symbol:
const BLANK = /\{\s*(?<name>\w+)\s*\}/g;

const fill = (template, values) =>
  template.replaceAll(BLANK, (blank, ...rest) => {
    const { name } = rest.at(-1);
    return Object.hasOwn(values, name) ? `${values[name]}` : blank;
  });

js-mh-line-reader.wrong-trim:
const createLineReader = onLine => {
  // The unfinished end of the text so far. Only this reader's methods see it.
  let held = "";
  const report = line => onLine(line.trim());
  return {
    push(chunk) {
      const pieces = (held + chunk).split("\n");
      held = pieces.pop(); // the last piece has no "\n" after it yet
      for (const line of pieces) report(line);
    },
    end() {
      if (held !== "") report(held);
      held = "";
    },
  };
};

js-mh2-top-scores.wrong-cap:
const createLeaderboard = size => {
  size = Math.min(size, 10); const board = []; // { name, score }, best first; every board has its own
  const placeOf = name => board.findIndex(entry => entry.name === name);
  return {
    add(name, score) {
      const old = placeOf(name);
      if (old !== -1) {
        if (board[old].score >= score) return old + 1; // not higher: nothing changes
        board.splice(old, 1); // the higher score replaces it
      }
      // The first entry the score beats: that puts it below every equal score.
      let at = board.findIndex(entry => entry.score < score);
      if (at === -1) at = board.length;
      if (at >= size) return null; // it does not make the board
      board.splice(at, 0, { name, score });
      board.splice(size); // whoever falls off the end
      return at + 1;
    },
    // New objects in a new array, so the caller cannot reach the board.
    top: () => board.map(({ name, score }) => ({ name, score })),
  };
};

js-throttle-calls.wrong-reset-timer:
const throttle = (fn, waitMs) => {
  let isWaiting = false;
  return (...args) => {
    if (isWaiting) {
      return;
    }
    isWaiting = true;
    fn(...args);
    setTimeout(() => {
      isWaiting = false;
    }, waitMs);
  };
};
